style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://files.oaiusercontent.com/file_0000000020e86209b26504b938bcc9a9") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Make the UI slightly transparent but clearer */
  .container, .navbar, .content, #nav-container {
    background-color: rgba(0, 0, 0, 0.4) !important; /* less dark */
    backdrop-filter: blur(2px) !important; /* less blurry */
  }

  /* Text styling for the vibe */
  p, span, h1, h2, h3, h4, h5, h6 {
    color: white !important;
    font-family: "Poppins", Arial, sans-serif !important;
  }
}
